from PIL import Image
import numpy as np
a=np.array(Image.open('first_frame.png').convert('RGB')).astype(float)
# Test exact line geometry by sampling pixel variance / means along candidate centerlines
def score(m,b,x0,x1):
 vals=[]
 for x in range(x0,x1):
  y=int(round(m*x+b));vals.append(a[y,x].mean())
 vals=np.array(vals)
 return vals.mean(),vals.std()
for name,x0,x1,ms in [('top',125,210,[-.13,-.12,-.11,-.10,-.09,-.08]),('mid',68,145,[.06,.08,.10,.12,.14]),('low',130,205,[-.1,-.08,-.06,-.04,-.02,0])]:
 print(name)
 for m in ms:
  best=None
  for b in np.arange(30,70,.5):
   sc=score(m,b,x0,x1)
   if best is None or sc[1]>best[0]:best=(sc[1],b,sc[0])
  print(m,'best',best)
