import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
# list high-blue/yellow pixels as rows with x ranges
for y in range(15,120):
    row=[]
    for x in range(60,220):
        r,g,b=im[y,x]
        if b>r*1.3 and b>g*1.1 and b>55: row.append(x)
    if row:
        # contiguous ranges
        chunks=[]; s=p=row[0]
        for x in row[1:]:
            if x>p+1: chunks.append((s,p));s=x
            p=x
        chunks.append((s,p))
        chunks=[c for c in chunks if c[1]-c[0]>=1]
        if chunks: print(y,chunks)
